// revalidation reaffirm a check that no longer exists — so the cross-file
// resolution is machine-held here; what the convention *means* stays in the
// writing-pack-prose skill.
//
// Two-root form: the path pattern keys on the `packs/<pack>/` suffix, so it
// matches the canon home's `packs/`, a member's `.claudinite/local/packs/` and
// the legacy `.claudinite/local_packs/` alike (a member's vendored
// `.claudinite/shared/` copy is linguist-vendored and never in the file set).
//
// RELEVANCE FIRST (engine/checks/README.md): the convention is opt-in per rule,
// so a pack with no markers and no check entries produces nothing.
const PROSE = /(^|\/)(?:local_)?packs\/[^/]+\/(?:RULES\.md|skills\/[^/]+\/SKILL\.md)$/;
const PACK_DIR = /(^|.*\/)(?:local_)?packs\/[^/]+\//;

// A citation marker: a line ENDING with `(3)` or `(3, 7)` — an inline issue id
// `(#1119)` or a worded parenthetical never matches, and a trailing period puts
// the marker after it by convention. A marker resolves within its own file's
// namespace: `(3)` in RULES.md cites the `RULES-3` entry, in a skill the
--- dedup worker 30-45

// The window this task's own cadence covers — `frequency: 'weekly'` in task.mjs.
export const WINDOW_DAYS = 7;

// A canon pack's file, in the two-root form: the mount prefix is optional because
// the canon home runs this same code from its repo root, where the shared packs
// ARE `packs/`. A local pack (`.claudinite/local/packs/…`, or the pre-rename
// `.claudinite/local_packs/…`) matches neither root — deliberately: it is what
// this task prunes, never the yardstick it prunes against.
const CANON_PACK_FILE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/.+/;

// A rule id as a pack's declared-checks.json spells it — `id`, the key that file
// actually uses (`rule` is the settings vocabulary for overriding one, a
// different file). A drift guard in the pack's tests parses the real
// declared-checks.json through this, because keyed on the wrong word it silently
// returns nothing on every real patch while fixtures stay green.
--- merge-rules
[
  {
    "name": "claudinite-local-pack-md-changes",
    "pathMatching": "/^\\.claudinite\\/(local\\/packs|local_packs)\\/.*\\.md$/",
    "changeKinds": ["added", "modified"],
    "editShape": "any"
  },
  {
    "name": "claudinite-local-pack-check-changes",
    "pathMatching": "/^\\.claudinite\\/(local\\/packs|local_packs)\\/[^/]+\\/(declared-checks\\.json|(workRules|worldRules)\\/[^/]+\\.mjs|skills\\/[^/]+\\/(declared-checks\\.json|checks\\.mjs)|test\\/.*\\.mjs)$/",
    "changeKinds": ["added", "modified"],
    "editShape": "any"
  }
]

